const state = {
  me: null,
  profile: null,
  profiles: [],
  interests: { incoming: [], outgoing: [], matches: [] },
  favorites: [],
  selectedChat: null,
  chatPolling: null,
  stickerTimer: null,
  photoData: ""
};

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];

function icon(name, size = 18) {
  const p = {
    heart: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="currentColor"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 1 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78Z"/></svg>`,
    search: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>`,
    user: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="4"/><path d="M5 21a7 7 0 0 1 14 0"/></svg>`,
    message: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 11.5a8.38 8.38 0 0 1-9 8.5 9.56 9.56 0 0 1-4-.8L3 21l1.8-4.1A8 8 0 1 1 21 11.5Z"/></svg>`,
    moon: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.8A8.5 8.5 0 1 1 11.2 3 6.7 6.7 0 0 0 21 12.8Z"/></svg>`,
    sun: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32 1.41 1.41M2 12h2m16 0h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/></svg>`,
    menu: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16M4 12h16M4 18h16"/></svg>`,
    x: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg>`,
    chevron: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m9 18 6-6-6-6"/></svg>`,
    check: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4L19 6"/></svg>`,
    shield: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/></svg>`,
    camera: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14.5 5H9.5L8 7H5a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-1.5-2Z"/><circle cx="12" cy="13" r="3.5"/></svg>`,
    image: `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m21 15-5-5L5 20"/></svg>`
  };
  return p[name] || "";
}

async function api(path, opts = {}) {
  const res = await fetch(path, {
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", ...(opts.headers || {}) },
    ...opts
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || "Something went wrong.");
  return data;
}

function toast(message) {
  const el = document.createElement("div");
  el.className = "toast";
  el.textContent = message;
  $("#toast-root").appendChild(el);
  setTimeout(() => el.remove(), 3000);
}

function setTheme() {
  const dark = localStorage.getItem("soulmate-theme") === "dark";
  document.documentElement.dataset.theme = dark ? "dark" : "light";
  const btn = $("#theme-btn");
  if (btn) btn.innerHTML = dark ? icon("sun") : icon("moon");
}
function toggleTheme() {
  const dark = localStorage.getItem("soulmate-theme") === "dark";
  localStorage.setItem("soulmate-theme", dark ? "light" : "dark");
  setTheme();
}

function escapeHTML(v) { return String(v ?? "").replace(/[&<>"']/g, m => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m])); }
function escapeAttr(v) { return escapeHTML(v).replace(/`/g, "&#096;"); }
function ageFromDob(dob) {
  if (!dob) return "—";
  const b = new Date(dob + "T00:00:00Z"), n = new Date();
  if (Number.isNaN(b.getTime())) return "—";
  let a = n.getUTCFullYear() - b.getUTCFullYear();
  if (n.getUTCMonth() < b.getUTCMonth() || (n.getUTCMonth() === b.getUTCMonth() && n.getUTCDate() < b.getUTCDate())) a--;
  return a;
}
function fallbackPhoto(gender) { return gender === "Male" ? "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=85" : "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=900&q=85"; }

function renderHome() {
  clearInterval(state.chatPolling);
  state.selectedChat = null;
  $("#app").innerHTML = `
  <div class="shell">
    <header class="topbar"><a class="brand" href="#home"><span class="brand-badge">${icon("heart",17)}</span>SoulMate</a>
      <nav class="nav-links"><a href="#home" data-scroll="home">Home</a><a href="#search" data-scroll="search">Search</a><a href="#how" data-scroll="how">How It Works</a><a href="#stories" data-scroll="stories">Stories</a><a href="#trust" data-scroll="trust">Safety</a></nav>
      <div class="nav-actions"><button id="theme-btn" class="icon-btn" aria-label="Toggle theme"></button><div class="desktop-auth"><button id="login-btn" class="btn btn-outline">Login</button><button id="admin-btn" class="btn btn-soft">Admin</button><button id="register-btn" class="btn btn-primary">Sign Up</button></div><button id="menu-btn" class="menu-btn">${icon("menu",22)}</button></div>
    </header>
    <div id="mobile-menu" class="mobile-menu"><a href="#home" data-scroll="home">Home</a><a href="#search" data-scroll="search">Search</a><a href="#how" data-scroll="how">How It Works</a><a href="#stories" data-scroll="stories">Stories</a><a href="#trust" data-scroll="trust">Safety</a><div class="mobile-menu-actions"><button id="mobile-login" class="btn btn-outline">Login</button><button id="mobile-register" class="btn btn-primary">Sign Up</button></div><button id="mobile-admin" class="btn btn-soft" style="width:100%;margin-top:7px">Admin Login</button></div>
    <main>
      ${homeHero()}
      ${homeStats()}
      ${homeSearch()}
      ${homeQuiz()}
      ${homePicks()}
      ${homeHow()}
      ${homeFun()}
      ${homeStories()}
      ${homeTrust()}
      ${homeCTA()}
    </main>
    ${footer()}
    ${homeSticker()}
    ${mobileHomeNav()}
  </div>`;
  setTheme();
  bindScrollLinks();
  $("#theme-btn").onclick = toggleTheme;
  $("#login-btn").onclick = () => openAuth("login");
  $("#admin-btn").onclick = () => openAuth("admin");
  $("#register-btn").onclick = () => openAuth("register");
  $("#mobile-login").onclick = () => openAuth("login");
  $("#mobile-register").onclick = () => openAuth("register");
  $("#mobile-admin").onclick = () => openAuth("admin");
  $("#menu-btn").onclick = () => $("#mobile-menu").classList.toggle("open");
  $("#hero-search").onclick = () => scrollToId("picks");
  $("#preview-match").onclick = openMatchModal;
  $("#cta-register").onclick = () => openAuth("register");
  $("#sticker-close")?.addEventListener("click", hideSticker);
  $$(".option").forEach(b => b.onclick = () => { b.parentElement.querySelectorAll(".option").forEach(x => x.classList.remove("sel")); b.classList.add("sel"); toast(`${b.dataset.option} — nice choice! ✨`); });
  $("#search-form").onsubmit = async e => { e.preventDefault(); const fd = new FormData(e.target); await loadPublicPicks(Object.fromEntries(fd.entries())); scrollToId("picks"); };
  $("#refresh-picks").onclick = () => loadPublicPicks({});
  showSticker("Hey there! 👋", "Ready to meet someone special?", "welcome");
  loadPublicPicks({});
}
function homeHero(){return `<section id="home" class="container hero"><div class="bg-glow g1"></div><div class="bg-glow g2"></div><div class="hero-copy"><div class="eyebrow">✦ A more fun way to meet</div><h1>Still Single?<br><span>Let's Fix That! ${icon("heart",42)}</span></h1><p class="hero-sub">Good things take time. But that doesn't mean you can't start looking.</p><p class="hero-p">Discover people, connect naturally, and start a conversation that could become something special.</p><div class="hero-buttons"><button id="hero-search" class="btn btn-primary btn-lg">Find My Match ${icon("chevron",18)}</button><a class="btn btn-outline btn-lg" href="#how">How It Works</a></div><div class="hero-mini"><div class="mini-avatars"><span>😊</span><span>🙂</span><span>😄</span><span>😉</span></div><div><b>50K+</b> happy connections</div></div></div><div class="hero-art"><div class="speech one">Good things<br>take time 💕</div><div class="speech two">Maybe it's<br>you? 👀</div><div class="float-heart fh1">✦</div><div class="float-heart fh2">♡</div><div class="float-heart fh3">✦</div><div class="cartoon a"><div class="hair black"></div><div class="head">😊</div><div class="torso blue"></div></div><div class="cartoon b"><div class="hair brown"></div><div class="head">🥰</div><div class="torso pink"></div></div><div class="hero-heart">${icon("heart",25)}</div></div></section>`}
function homeStats(){return `<div class="container stats"><div class="stat"><b>50K+</b><span>Happy connections</span></div><div class="stat"><b>200K+</b><span>Active profiles</span></div><div class="stat"><b>4.8/5</b><span>Community rating</span></div><div class="stat"><b>24/7</b><span>Report tools</span></div></div>`}
function homeSearch(){return `<section id="search"><div class="container"><div class="section-title"><div><div class="eyebrow">⌕ Start exploring</div><h2>Find Your Special Someone 💕</h2><p>Start with what matters to you.</p></div></div><form id="search-form" class="search-card"><label class="field"><span>Looking for</span><select name="gender"><option value="">Everyone</option><option>Female</option><option>Male</option></select></label><label class="field"><span>Age range</span><div class="age-row"><select name="minAge"><option>18</option><option selected>22</option><option>24</option><option>26</option><option>28</option></select><span>to</span><select name="maxAge"><option>28</option><option selected>32</option><option>35</option><option>38</option><option>40</option></select></div></label><label class="field"><span>Location</span><select name="location"><option value="">Anywhere</option><option selected>Kerala</option><option>Karnataka</option><option>Tamil Nadu</option></select></label><label class="field"><span>Religion</span><select name="religion"><option value="">Any</option><option>Christian</option><option>Hindu</option><option>Muslim</option></select></label><button class="btn btn-primary search-submit">${icon("search",18)} Search Profiles</button></form></div></section>`}
function homeQuiz(){return `<section class="quiz"><div class="section-title center container"><div><div class="eyebrow">☺ Make it personal</div><h2>Before You Match… 👀</h2><p>A little personality says more than a long bio.</p></div></div><div class="quiz-grid">${[["01","Your ideal first date?",["☕ Coffee","🍕 Food","🎬 Movie","🌊 Beach","🚗 Road trip"]],["02","Beach or mountains?",["🏖️ Beach","🏔️ Mountains"]],["03","Tea or coffee?",["🍵 Tea","☕ Coffee"]]].map(q=>`<div class="quiz-card"><div class="quiz-no">${q[0]}</div><h3>${q[1]}</h3><div class="options">${q[2].map(o=>`<button class="option" data-option="${o}">${o}</button>`).join("")}</div></div>`).join("")}</div></section>`}
function homePicks(){return `<section id="picks"><div class="container"><div class="section-title"><div><div class="eyebrow">✦ Fresh today</div><h2>Today's Picks</h2><p>Approved profiles available to discover right now.</p></div><button id="refresh-picks" class="btn btn-soft">Refresh ${icon("chevron",16)}</button></div><div id="profile-grid" class="profile-grid"></div></div></section>`}
function homeHow(){return `<section id="how" class="steps"><div class="section-title center container"><div><div class="eyebrow">◎ Simple by design</div><h2>How It Works 💘</h2><p>No complicated steps. Just meet, match and talk.</p></div></div><div class="step-grid">${[["01","Create Your Profile","Tell people what makes you, you."],["02","Discover People","Use preferences to explore profiles."],["03","Send an Interest","A simple hello can be the beginning."],["04","Start Talking","Chat after a mutual match."]].map(x=>`<div class="step"><div class="step-top"><span class="step-num">${x[0]}</span><span>✦</span></div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join("")}</div></section>`}
function homeFun(){return `<section class="playful"><div class="container fun-panel"><div><div class="eyebrow">✦ A little extra fun</div><h2>A Little More Fun Than <span>“Hello”</span> 😄</h2><p>Playful stickers turn everyday actions into tiny moments of celebration.</p><button id="preview-match" class="btn btn-primary">Preview Match Animation ✨</button></div><div class="sticker-grid">${[["👋","Login","“Hey there!”"],["🎉","Profile complete","“Unlocked!”"],["💌","Interest sent","“Fingers crossed!”"],["💬","New message","“Come say hi!”"]].map(x=>`<div class="mini-sticker"><i>${x[0]}</i><b>${x[1]}</b><span>${x[2]}</span></div>`).join("")}</div></div></section>`}
function homeStories(){return `<section id="stories"><div class="container"><div class="section-title center"><div><div class="eyebrow">♥ Community stories</div><h2>People Who Found Their Person</h2><p>Demo testimonials for the current site.</p></div></div><div class="story-grid">${[["We started with one simple conversation and ended up planning our wedding.","Nikhil & Riya"],["The profile questions made it so easy to start talking.","Arjun & Meera"],["It felt friendly instead of feeling like a form to fill out.","Joel & Anna"]].map(x=>`<div class="quote-card"><div class="quote-mark">“</div><p>${x[0]}</p><b>${x[1]}</b><span>Demo story</span></div>`).join("")}</div></div></section>`}
function homeTrust(){return `<section id="trust"><div class="container trust"><div><div class="eyebrow">${icon("shield",14)} Built with care</div><h2>Your privacy and safety come first.</h2><p>Keep contact details private, block unwanted users, and report problems. Admin approval is included.</p></div><div class="trust-grid">${[["🔒","Privacy First","Control what you share."],["🛡️","Safer Profiles","Admin approval workflow included."],["🚩","Report & Block","Simple tools for unwanted behavior."],["♥","Respectful","Matching never overrides consent."]].map(x=>`<div class="trust-card"><div style="font-size:20px">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join("")}</div></div></section>`}
function homeCTA(){return `<section class="cta"><div class="container"><div class="cta-hearts">♡ ✦ ♥ ✦ ♡</div><h2>Maybe Your Person Is Already Here. ❤️</h2><p>Take the first step. It's completely free.</p><button id="cta-register" class="btn btn-primary btn-lg">Create My Profile ${icon("chevron",18)}</button></div></section>`}
function footer(){return `<footer class="footer"><div class="container footer-inner"><div><div class="brand"><span class="brand-badge">${icon("heart",15)}</span>SoulMate</div><p>Meet. Match. Maybe Forever.</p></div><div class="footer-links"><a href="#home">Home</a><a href="#search">Search</a><a href="#how">How It Works</a><a href="#trust">Safety</a><a href="#">Privacy</a><a href="#">Terms</a></div><div class="copy">© 2026 SoulMate · Free forever · No payments</div></div></footer>`}
function mobileHomeNav(){return `<nav class="mobile-nav"><a href="#home" data-scroll="home" class="active">⌂<span>Home</span></a><a href="#search" data-scroll="search">${icon("search",19)}<span>Search</span></a><a href="#picks" data-scroll="picks">${icon("heart",19)}<span>Picks</span></a><a href="#how" data-scroll="how">${icon("message",19)}<span>How</span></a><a href="#trust" data-scroll="trust">${icon("user",19)}<span>About</span></a></nav>`}
function bindScrollLinks(){ $$("[data-scroll]").forEach(a=>a.onclick=e=>{e.preventDefault();scrollToId(a.dataset.scroll);$("#mobile-menu")?.classList.remove("open");$$('.mobile-nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active');}); }
function scrollToId(id){document.getElementById(id)?.scrollIntoView({behavior:"smooth",block:"start"});}

async function loadPublicPicks(filters={}) { try { const data=await api("/api/public-profiles?"+new URLSearchParams(filters)); state.profiles=data.profiles; renderProfileGrid($("#profile-grid"),state.profiles,true); } catch(e){ toast(e.message); } }

function renderProfileGrid(root,list,isPublic=false){ if(!root)return; if(!list.length){root.innerHTML=`<div class="empty" style="grid-column:1/-1">No profiles match these filters yet. Try different preferences 😅</div>`;return;} root.innerHTML=list.map(profileCardHTML).join(""); wireProfileCards(root,isPublic); }
function profileCardHTML(p){return `<article class="profile-card"><div class="profile-img"><img src="${escapeAttr(p.photo||fallbackPhoto(p.gender))}" alt="${escapeAttr(p.name)}" loading="lazy"><button class="fav profile-fav" data-id="${p.id}" aria-label="Favorite ${escapeAttr(p.name)}">${icon("heart",18)}</button><span class="photo-pill">✓ Profile</span></div><div class="profile-meta"><div class="name-row"><h3>${escapeHTML(p.name)}, ${p.age ?? ""}</h3><span class="verified">✓</span></div><div class="meta-line">📍 ${escapeHTML(p.city||"Location hidden")}</div><div class="meta-line">💼 ${escapeHTML(p.occupation||"Not added")}</div><div class="tags">${(p.interests||[]).slice(0,3).map(t=>`<span>${escapeHTML(t)}</span>`).join("")}</div><div class="profile-actions"><button class="small-btn profile-view" data-id="${p.id}">View Profile</button><button class="small-btn primary profile-interest" data-id="${p.id}">♡ Interest</button></div></div></article>`}
function wireProfileCards(root,isPublic=false){ $$(".profile-view",root).forEach(b=>b.onclick=()=>{ if(isPublic){toast("Login to view and connect with profiles.");openAuth("login");}else openProfile(b.dataset.id); }); $$(".profile-fav",root).forEach(b=>b.onclick=async()=>{ if(isPublic){toast("Login to save favorites.");openAuth("login");return;} try{const d=await api("/api/favorites",{method:"POST",body:JSON.stringify({targetId:b.dataset.id})});b.classList.toggle("liked",d.favorited);toast(d.favorited?"Added to favorites ❤️":"Removed from favorites"); if(state.me)loadFavorites();}catch(e){toast(e.message)}}); $$(".profile-interest",root).forEach(b=>b.onclick=async()=>{ if(isPublic){toast("Login to send an interest.");openAuth("login");return;} try{const d=await api("/api/interests",{method:"POST",body:JSON.stringify({targetId:b.dataset.id})});toast(d.message);await loadInterests();if(d.interest?.status==="accepted")openMatchModal();}catch(e){toast(e.message)}}); }

function homeSticker(){return `<div id="welcome-sticker" class="sticker hidden"><button id="sticker-close" class="sticker-close">${icon("x",14)}</button><div class="sticker-bubble"><b id="sticker-title">Hey there! 👋</b><span id="sticker-message">Ready to meet someone special?</span></div><div class="sticker-avatar">👋</div></div>`}
function showSticker(title,message,type="welcome"){ let s=$("#welcome-sticker"); if(!s){s=document.createElement("div");s.id="welcome-sticker";s.className="sticker";document.body.appendChild(s);} s.classList.remove("hidden","exit");s.innerHTML=`<button class="sticker-close" aria-label="Close">${icon("x",14)}</button><div class="sticker-bubble"><b>${escapeHTML(title)}</b><span>${escapeHTML(message)}</span></div><div class="sticker-avatar">${type==="match"?"💘":type==="message"?"💬":type==="complete"?"🎉":"👋"}</div>`;s.querySelector(".sticker-close").onclick=hideSticker;clearTimeout(state.stickerTimer);state.stickerTimer=setTimeout(hideSticker,7000);}
function hideSticker(){const s=$("#welcome-sticker");if(!s)return;s.classList.add("exit");clearTimeout(state.stickerTimer);setTimeout(()=>s?.remove(),550);}

function openAuth(mode="login"){ const isAdmin=mode==="admin";const isLogin=mode==="login"||isAdmin;showModal(`<div class="modal small auth-modal"><button class="close" id="modal-close">${icon("x",17)}</button><div class="eyebrow">${isAdmin?"◎ Administrator":isLogin?"♥ Welcome back":"✦ Start your story"}</div><h2>${isAdmin?"Admin Login":isLogin?"Log in to SoulMate":"Create your free account"}</h2><p class="help">${isAdmin?"Manage profile approvals, reports and users.":isLogin?"Your next conversation could be waiting.":"No payments. No subscriptions. Completely free."}</p><form id="auth-form">${!isLogin?`<label class="field"><span>Name</span><input name="name" required maxlength="80" placeholder="Your name"></label><div style="height:10px"></div><label class="field"><span>Gender</span><select name="gender" required><option value="">Select</option><option>Female</option><option>Male</option></select></label><div style="height:10px"></div>`:""}<label class="field"><span>Email</span><input type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label><div style="height:10px"></div><label class="field"><span>Password</span><input type="password" name="password" required minlength="8" autocomplete="${isLogin?"current-password":"new-password"}" placeholder="At least 8 characters"></label><div class="form-actions">${!isAdmin?`<button type="button" id="switch-auth" class="btn btn-outline">${isLogin?"Create account":"Already have an account?"}</button>`:""}<button class="btn btn-primary" type="submit">${isAdmin?"Enter Admin Panel":isLogin?"Login":"Create account"}</button></div></form>${!isAdmin?`<div class="auth-divider"><span>or</span></div><div id="google-wrap"><div id="google-button"></div><small id="google-help">Google sign-in can be enabled with your Google OAuth client ID.</small></div>`:""}</div>`); $("#modal-close").onclick=closeModal;if($("#switch-auth"))$("#switch-auth").onclick=()=>{closeModal();openAuth(isLogin?"register":"login")};$("#auth-form").onsubmit=async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.target).entries());const d=await api(`/api/auth/${isLogin?"login":"register"}`,{method:"POST",body:JSON.stringify(body)});state.me=d.user;const me=await api("/api/me");state.profile=me.profile;closeModal();if(state.me.role==="admin"){renderAdmin();showSticker("Admin access granted 🛡️","Welcome to the moderation panel.","complete");}else{renderDashboard();showSticker(isLogin?`Welcome back, ${state.me.name}! 👋`:"Account created! ✨","Let's finish your profile and meet new people.","complete");}}catch(err){toast(err.message)}};if(!isAdmin)setupGoogleButton(); }

async function setupGoogleButton(){const help=$("#google-help");try{const cfg=await api("/api/config");if(!cfg.googleClientId){help.textContent="Google sign-in is not configured yet. Add GOOGLE_CLIENT_ID to enable it.";help.classList.add("warn");return;}if(!window.google?.accounts?.id){help.textContent="Loading Google sign-in…";setTimeout(setupGoogleButton,600);return;}google.accounts.id.initialize({client_id:cfg.googleClientId,callback:handleGoogleCredential,auto_select:false});const box=$("#google-button");if(box){google.accounts.id.renderButton(box,{theme:"outline",size:"large",shape:"pill",text:"continue_with",width:330});help.textContent="Continue securely with your Google account.";}}catch(e){help.textContent="Google sign-in could not be loaded.";help.classList.add("warn");}}
async function handleGoogleCredential(response){try{const d=await api("/api/auth/google",{method:"POST",body:JSON.stringify({credential:response.credential})});state.me=d.user;const me=await api("/api/me");state.profile=me.profile;closeModal();renderDashboard();showSticker(`Welcome, ${state.me.name}! 👋`,`Signed in securely with Google.`,"complete");}catch(e){toast(e.message);}}

function renderDashboard(){clearInterval(state.chatPolling);$("#app").innerHTML=`<div class="shell"><header class="topbar dashboard-topbar"><a class="brand" href="#dash-home"><span class="brand-badge">${icon("heart",17)}</span>SoulMate</a><nav class="nav-links"><a href="#dash-home" data-scroll="dash-home">Home</a><a href="#today" data-scroll="today">Today's Picks</a><a href="#browse" data-scroll="browse">Search</a><a href="#interests" data-scroll="interests">Interests</a><a href="#favorites" data-scroll="favorites">Favorites</a><a href="#messages" data-scroll="messages">Chat</a><a href="#my-profile" data-scroll="my-profile">Profile</a></nav><div class="nav-actions"><button id="theme-btn" class="icon-btn">${icon("moon")}</button><button id="logout" class="btn btn-outline desktop-auth">Logout</button><button id="menu-btn" class="menu-btn">${icon("menu",22)}</button></div></header><div id="mobile-menu" class="mobile-menu"><a href="#dash-home" data-scroll="dash-home">Home</a><a href="#today" data-scroll="today">Today's Picks</a><a href="#browse" data-scroll="browse">Search</a><a href="#interests" data-scroll="interests">Interests</a><a href="#favorites" data-scroll="favorites">Favorites</a><a href="#messages" data-scroll="messages">Chat</a><a href="#my-profile" data-scroll="my-profile">Profile</a><button id="mobile-logout" class="btn btn-outline" style="width:100%;margin-top:7px">Logout</button></div><main>${dashboardHome()}${dashboardToday()}${dashboardBrowse()}${dashboardInterests()}${dashboardFavorites()}${dashboardMessages()}${dashboardProfile()}</main><footer class="footer"><div class="container footer-inner"><div><div class="brand"><span class="brand-badge">${icon("heart",15)}</span>SoulMate</div><p>Free forever · no payments.</p></div><div class="footer-links"><a href="#dash-home">Home</a><a href="#today">Today's Picks</a><a href="#messages">Chat</a></div><div class="copy">© 2026 SoulMate</div></div></footer>${dashboardSticker()}${dashboardMobileNav()}</div>`;setTheme();bindScrollLinks();$("#theme-btn").onclick=toggleTheme;$("#logout").onclick=logout;$("#mobile-logout").onclick=logout;$("#menu-btn").onclick=()=>$("#mobile-menu").classList.toggle("open");$("#edit-profile").onclick=openProfileEditor;$("#edit-profile-2")?.addEventListener("click",openProfileEditor);$("#refresh-today").onclick=loadTodayPicks;const form=$("#dashboard-search");if(form)form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());await loadBrowse(fd);scrollToId("browse");};loadTodayPicks();loadBrowse({});loadInterests();loadFavorites();renderMyProfile();renderChat();showSticker(`Welcome back, ${state.me.name}! 👋`,state.profile?.approved?"Your profile is live. Let's find a good connection.":"Finish your profile and submit it for approval.","welcome");}
function dashboardHome(){return `<section id="dash-home"><div class="container"><div class="section-title"><div><div class="eyebrow">✦ Your dashboard</div><h2>Hi, ${escapeHTML(state.me.name)} <span>👋</span></h2><p>${state.profile?.approved?"Your profile is approved and visible.":"Your profile is waiting for admin approval after you complete it."}</p></div><button id="edit-profile" class="btn btn-primary">Edit Profile</button></div><div class="dashboard-banner"><div><div class="eyebrow">✦ Free forever</div><h3>${state.profile?.approved?"You're ready to connect.":"Let's get your profile ready."}</h3><p>${state.profile?.approved?"Browse profiles, send interests and chat after a mutual match.":"Add your details and photo, then an admin can approve your profile."}</p></div><div class="banner-emoji">💘</div></div></div></section>`}
function dashboardToday(){return `<section id="today"><div class="container"><div class="section-title"><div><div class="eyebrow">✦ Fresh for you</div><h2>Today's Picks</h2><p>Quick suggestions based on the profiles available to you.</p></div><button id="refresh-today" class="btn btn-soft">Refresh picks ${icon("chevron",16)}</button></div><div id="today-grid" class="profile-grid"></div></div></section>`}
function dashboardBrowse(){return `<section id="browse"><div class="container"><div class="section-title"><div><div class="eyebrow">⌕ Explore</div><h2>Search Profiles</h2><p>Adjust filters anytime.</p></div></div><form id="dashboard-search" class="search-card"><label class="field"><span>Looking for</span><select name="gender"><option value="">Everyone</option><option>Female</option><option>Male</option></select></label><label class="field"><span>Age range</span><div class="age-row"><select name="minAge"><option>18</option><option selected>22</option><option>24</option><option>26</option><option>28</option></select><span>to</span><select name="maxAge"><option>28</option><option selected>32</option><option>35</option><option>38</option><option>40</option></select></div></label><label class="field"><span>Location</span><select name="location"><option value="">Anywhere</option><option selected>Kerala</option><option>Karnataka</option><option>Tamil Nadu</option></select></label><label class="field"><span>Religion</span><select name="religion"><option value="">Any</option><option>Christian</option><option>Hindu</option><option>Muslim</option></select></label><button class="btn btn-primary search-submit">${icon("search",18)} Search</button></form><div id="browse-grid" class="profile-grid" style="margin-top:22px"></div></div></section>`}
function dashboardInterests(){return `<section id="interests"><div class="container"><div class="section-title"><div><div class="eyebrow">♥ Connections</div><h2>Interests & Matches</h2><p>Accept an interest to create a mutual match and unlock chat.</p></div></div><div id="interest-area"></div></div></section>`}
function dashboardFavorites(){return `<section id="favorites"><div class="container"><div class="section-title"><div><div class="eyebrow">♡ Saved people</div><h2>Favorites</h2><p>People you saved for later.</p></div></div><div id="favorite-grid" class="profile-grid"></div></div></section>`}
function dashboardMessages(){return `<section id="messages"><div class="container"><div class="section-title"><div><div class="eyebrow">💬 Conversations</div><h2>Chat</h2><p>Chat is unlocked after a mutual match.</p></div></div><div id="chat-area"></div></div></section>`}
function dashboardProfile(){const p=state.profile||{};return `<section id="my-profile"><div class="container"><div class="section-title"><div><div class="eyebrow">◎ Your story</div><h2>My Profile</h2><p>Keep your details and photo up to date.</p></div></div><div id="my-profile-card"></div></div></section>`}
function dashboardSticker(){return `<div id="welcome-sticker" class="sticker hidden"></div>`}
function dashboardMobileNav(){return `<nav class="mobile-nav"><a href="#dash-home" data-scroll="dash-home" class="active">⌂<span>Home</span></a><a href="#today" data-scroll="today">${icon("heart",19)}<span>Picks</span></a><a href="#browse" data-scroll="browse">${icon("search",19)}<span>Search</span></a><a href="#messages" data-scroll="messages">${icon("message",19)}<span>Chat</span></a><a href="#my-profile" data-scroll="my-profile">${icon("user",19)}<span>Profile</span></a></nav>`}

async function loadTodayPicks(){try{const d=await api("/api/profiles?"+new URLSearchParams({minAge:"18",maxAge:"60",location:""}));let list=d.profiles.slice().sort(()=>Math.random()-.5).slice(0,4);renderProfileGrid($("#today-grid"),list,false);}catch(e){toast(e.message)}}
async function loadBrowse(filters={}){try{const d=await api("/api/profiles?"+new URLSearchParams(filters));state.profiles=d.profiles;renderProfileGrid($("#browse-grid"),d.profiles,false);}catch(e){toast(e.message)}}
async function loadInterests(){try{state.interests=await api("/api/interests");renderInterests();renderChat();}catch(e){toast(e.message)}}
function renderInterests(){const el=$("#interest-area");if(!el)return;const inc=state.interests.incoming,out=state.interests.outgoing,mat=state.interests.matches;el.innerHTML=`<div class="three-grid"><div class="card"><h3>Incoming 💌</h3>${inc.length?inc.map(x=>`<div class="mini-row"><div><b>${escapeHTML(x.profile.name)}, ${x.profile.age}</b><small>📍 ${escapeHTML(x.profile.city||"")}</small></div>${x.status==="pending"?`<div class="mini-actions"><button class="btn btn-success interest-action" data-id="${x.id}" data-action="accept">Accept</button><button class="btn btn-danger interest-action" data-id="${x.id}" data-action="reject">Reject</button></div>`:`<span class="state-pill">${escapeHTML(x.status)}</span>`}</div>`).join(""):`<div class="empty">No incoming interests yet.</div>`}</div><div class="card"><h3>Sent 💌</h3>${out.length?out.map(x=>`<div class="mini-row"><div><b>${escapeHTML(x.profile.name)}, ${x.profile.age}</b><small>${x.status==="accepted"?"❤️ Matched":"⏳ "+escapeHTML(x.status)}</small></div></div>`).join(""):`<div class="empty">No outgoing interests yet.</div>`}</div><div class="card"><h3>Matches 🎉</h3>${mat.length?mat.map(x=>`<div class="mini-row"><div><b>${escapeHTML(x.name)}, ${x.age}</b><small>📍 ${escapeHTML(x.city||"")}</small></div><button class="btn btn-primary open-chat" data-id="${x.id}">Chat</button></div>`).join(""):`<div class="empty">No matches yet. Keep exploring 💕</div>`}</div></div>`;$$('.interest-action').forEach(b=>b.onclick=async()=>{try{const d=await api(`/api/interests/${b.dataset.id}/${b.dataset.action}`,{method:"POST"});toast(d.message);await loadInterests();if(d.matched)openMatchModal();}catch(e){toast(e.message)}});$$('.open-chat').forEach(b=>b.onclick=()=>openChatWith(b.dataset.id));}
async function loadFavorites(){try{const d=await api("/api/favorites");state.favorites=d.profiles;renderProfileGrid($("#favorite-grid"),d.profiles,false);}catch(e){toast(e.message)}}
function renderMyProfile(){const el=$("#my-profile-card");if(!el)return;const p=state.profile;if(!p){el.innerHTML='<div class="empty card">Create your profile to get started.</div>';return}el.innerHTML=`<div class="card profile-preview"><div class="my-photo-wrap"><img src="${escapeAttr(p.photo||fallbackPhoto(p.gender))}" alt="My profile photo"><span class="profile-photo-badge">${p.approved?"✓ Approved":"⏳ Pending"}</span></div><div><div class="name-row"><h3>${escapeHTML(state.me.name)}</h3>${p.approved?'<span class="verified">✓</span>':''}</div><div class="meta-line">📍 ${escapeHTML(p.city||"Location not added")}${p.state?", "+escapeHTML(p.state):""}</div><div class="meta-line">💼 ${escapeHTML(p.occupation||"Occupation not added")}</div><p class="bio-text">${escapeHTML(p.about||"Add a short introduction to help people get to know you.")}</p><div class="tags">${(p.interests||[]).map(x=>`<span>${escapeHTML(x)}</span>`).join("")}</div><button id="edit-profile-2" class="btn btn-primary">Edit Profile</button></div></div><div class="detail-list">${[["Gender",p.gender],["Age",ageFromDob(p.dob)],["Height",p.height],["Education",p.education],["Religion",p.religion],["Community",p.community],["Mother tongue",p.motherTongue],["Country",p.country]].map(x=>`<div class="detail"><b>${x[0]}</b><span>${escapeHTML(String(x[1]||"—"))}</span></div>`).join("")}</div>`;$("#edit-profile-2").onclick=openProfileEditor}

function openProfileEditor(){const p=state.profile||{};state.photoData="";showModal(`<div class="modal"><button class="close" id="modal-close">${icon("x",17)}</button><div class="eyebrow">◎ Build your profile</div><h2>Edit your profile</h2><p class="help">Choose a photo from your phone or PC. Your selected image is resized in the browser before it is saved.</p><form id="profile-form"><div class="photo-upload"><div class="upload-preview"><img id="upload-preview" src="${escapeAttr(p.photo||fallbackPhoto(p.gender))}" alt="Preview"></div><div><label for="profile-photo" class="upload-btn">${icon("camera",17)} Choose profile photo</label><input id="profile-photo" type="file" accept="image/*" hidden><div class="upload-note">JPG, PNG or WEBP · max recommended 5 MB</div></div></div><div class="form-grid"><label class="field"><span>Name</span><input name="name" value="${escapeAttr(state.me.name)}" required></label><label class="field"><span>Gender</span><select name="gender"><option ${p.gender==="Female"?"selected":""}>Female</option><option ${p.gender==="Male"?"selected":""}>Male</option></select></label><label class="field"><span>Date of birth</span><input type="date" name="dob" value="${escapeAttr(p.dob||"")}"></label><label class="field"><span>Height</span><input name="height" value="${escapeAttr(p.height||"")}" placeholder="165 cm"></label><label class="field"><span>Religion</span><select name="religion"><option value="">Prefer not to say</option><option ${p.religion==="Christian"?"selected":""}>Christian</option><option ${p.religion==="Hindu"?"selected":""}>Hindu</option><option ${p.religion==="Muslim"?"selected":""}>Muslim</option></select></label><label class="field"><span>Community</span><input name="community" value="${escapeAttr(p.community||"")}" placeholder="Any / community"></label><label class="field"><span>Mother tongue</span><input name="motherTongue" value="${escapeAttr(p.motherTongue||"")}"></label><label class="field"><span>Education</span><input name="education" value="${escapeAttr(p.education||"")}"></label><label class="field"><span>Occupation</span><input name="occupation" value="${escapeAttr(p.occupation||"")}"></label><label class="field"><span>City</span><input name="city" value="${escapeAttr(p.city||"")}"></label><label class="field"><span>State</span><input name="state" value="${escapeAttr(p.state||"Kerala")}"></label><label class="field"><span>Country</span><input name="country" value="${escapeAttr(p.country||"India")}"></label><label class="field form-full"><span>About you</span><textarea name="about" rows="4" maxlength="800">${escapeHTML(p.about||"")}</textarea></label><label class="field"><span>Partner gender</span><select name="prefGender"><option>Everyone</option><option ${p.preference?.gender==="Female"?"selected":""}>Female</option><option ${p.preference?.gender==="Male"?"selected":""}>Male</option></select></label><label class="field"><span>Preferred location</span><select name="prefLocation"><option>Anywhere</option><option ${p.preference?.location==="Kerala"?"selected":""}>Kerala</option><option>Karnataka</option><option>Tamil Nadu</option></select></label><label class="field"><span>Partner min age</span><input type="number" min="18" max="80" name="prefMin" value="${p.preference?.minAge||22}"></label><label class="field"><span>Partner max age</span><input type="number" min="18" max="80" name="prefMax" value="${p.preference?.maxAge||35}"></label><label class="field form-full"><span>Interests (comma separated)</span><input name="interests" value="${escapeAttr((p.interests||[]).join(", "))}" placeholder="Travel, Music, Food"></label></div><div class="form-actions"><button type="button" id="modal-cancel" class="btn btn-outline">Cancel</button><button class="btn btn-primary" type="submit">Save Profile</button></div></form></div>`);$("#modal-close").onclick=closeModal;$("#modal-cancel").onclick=closeModal;$("#profile-photo").onchange=e=>handlePhotoFile(e.target.files?.[0]);$("#profile-form").onsubmit=saveProfile;}
async function handlePhotoFile(file){if(!file)return;if(!file.type.startsWith("image/")){toast("Please choose an image file.");return;}if(file.size>8*1024*1024){toast("Please choose an image smaller than 8 MB.");return;}try{const data=await compressImage(file,1200,.82);state.photoData=data;$("#upload-preview").src=data;toast("Photo ready to save 📸");}catch(e){toast("Could not process this image.")}}
function compressImage(file,maxSize,quality){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,maxSize/Math.max(img.width,img.height));const c=document.createElement("canvas");c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const ctx=c.getContext("2d");ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL("image/jpeg",quality));};img.onerror=reject;img.src=reader.result;};reader.onerror=reject;reader.readAsDataURL(file);});}
async function saveProfile(e){e.preventDefault();const fd=Object.fromEntries(new FormData(e.target).entries());try{const d=await api("/api/profile",{method:"PUT",body:JSON.stringify({name:fd.name,gender:fd.gender,dob:fd.dob,height:fd.height,religion:fd.religion,community:fd.community,motherTongue:fd.motherTongue,education:fd.education,occupation:fd.occupation,city:fd.city,state:fd.state,country:fd.country,photo:state.photoData||state.profile?.photo||"",about:fd.about,interests:fd.interests.split(",").map(s=>s.trim()).filter(Boolean),preference:{gender:fd.prefGender,minAge:fd.prefMin,maxAge:fd.prefMax,location:fd.prefLocation}})});state.me=d.user;state.profile=d.profile;closeModal();renderDashboard();showSticker("Profile saved! 🎉",d.profile.approved?"Your updates are live.":"Your profile was sent back for approval.","complete");}catch(err){toast(err.message)}}

async function openProfile(id){try{const d=await api(`/api/profiles/${id}`);showModal(profileDetail(d.profile,d.interest,d.canChat));wireDetail(d.profile,d.interest,d.canChat);}catch(e){toast(e.message)}}
function profileDetail(p,interest,canChat){return `<div class="modal"><button class="close" id="modal-close">${icon("x",17)}</button><div class="profile-preview"><img src="${escapeAttr(p.photo||fallbackPhoto(p.gender))}" alt="${escapeAttr(p.name)}"><div><div class="name-row"><h3 style="font-size:25px">${escapeHTML(p.name)}, ${p.age}</h3><span class="verified">✓</span></div><div class="meta-line">📍 ${escapeHTML(p.city||"")}, ${escapeHTML(p.state||"")}</div><div class="meta-line">💼 ${escapeHTML(p.occupation||"")}</div><p class="bio-text">${escapeHTML(p.about||"No bio added yet.")}</p><div class="tags">${(p.interests||[]).map(t=>`<span>${escapeHTML(t)}</span>`).join("")}</div><div class="detail-buttons"><button class="btn btn-primary" id="detail-interest">${interest==="accepted"?"Matched ❤️":interest==="pending"?"Interest sent":"Send Interest 💌"}</button>${canChat?`<button class="btn btn-outline" id="detail-chat">Chat ${icon("message",16)}</button>`:""}<button class="btn btn-danger" id="detail-block">Block</button><button class="btn btn-outline" id="detail-report">Report</button></div></div></div><div class="detail-list">${[["Height",p.height],["Education",p.education],["Religion",p.religion],["Community",p.community],["Mother tongue",p.motherTongue],["Country",p.country]].map(x=>`<div class="detail"><b>${x[0]}</b><span>${escapeHTML(String(x[1]||"—"))}</span></div>`).join("")}</div></div>`}
function wireDetail(p,interest,canChat){$("#modal-close").onclick=closeModal;$("#detail-interest").onclick=async()=>{if(interest!==null)return;try{const d=await api("/api/interests",{method:"POST",body:JSON.stringify({targetId:p.id})});toast(d.message);closeModal();await loadInterests();if(d.interest?.status==="accepted")openMatchModal();}catch(e){toast(e.message)}};$("#detail-chat")?.addEventListener("click",()=>{closeModal();openChatWith(p.id)});$("#detail-block").onclick=async()=>{try{await api("/api/blocks",{method:"POST",body:JSON.stringify({targetId:p.id})});closeModal();toast("Profile blocked.");renderDashboard();}catch(e){toast(e.message)}};$("#detail-report").onclick=async()=>{const reason=prompt("Reason for report?","Inappropriate behavior");if(!reason)return;try{await api("/api/reports",{method:"POST",body:JSON.stringify({targetId:p.id,reason})});toast("Report submitted.");}catch(e){toast(e.message)}}}

function renderChat(){const el=$("#chat-area");if(!el)return;const matches=state.interests.matches||[];if(!matches.length){el.innerHTML='<div class="empty card">No matches yet. Accept an interest and your chat will appear here 💬</div>';return;}if(!state.selectedChat)state.selectedChat=matches[0].id;el.innerHTML=`<div class="chat-layout"><div class="chat-list">${matches.map(p=>`<button class="chat-person ${p.id===state.selectedChat?"active":""}" data-id="${p.id}"><img class="chat-avatar" src="${escapeAttr(p.photo||fallbackPhoto(p.gender))}" alt=""><span><b>${escapeHTML(p.name)}</b><small>${escapeHTML(p.city||"")}</small></span></button>`).join("")}</div><div class="chat-window"><div id="chat-head" class="chat-head">Chat</div><div id="chat-messages" class="chat-messages"></div><form id="chat-compose" class="chat-compose"><input name="message" maxlength="1000" autocomplete="off" placeholder="Type a friendly message…"><button class="btn btn-primary">Send</button></form></div></div>`;$$('.chat-person').forEach(b=>b.onclick=()=>openChatWith(b.dataset.id));$("#chat-compose").onsubmit=async e=>{e.preventDefault();const message=new FormData(e.target).get("message").trim();if(!message)return;try{await api("/api/messages",{method:"POST",body:JSON.stringify({toId:state.selectedChat,message})});e.target.reset();await loadChatMessages();showSticker("New message sent 💬","Your message is on its way.","message");}catch(err){toast(err.message)}};loadChatMessages();clearInterval(state.chatPolling);state.chatPolling=setInterval(()=>loadChatMessages(true),2500);}
async function openChatWith(id){state.selectedChat=id;renderChat();scrollToId("messages");}
async function loadChatMessages(silent=false){if(!state.selectedChat)return;try{const d=await api(`/api/messages?with=${encodeURIComponent(state.selectedChat)}`);const area=$("#chat-messages");if(!area)return;area.innerHTML=d.messages.length?d.messages.map(m=>`<div class="bubble ${m.mine?"mine":"theirs"}">${escapeHTML(m.message)}</div>`).join(""):`<div class="empty">Start the conversation with a simple hello 👋</div>`;area.scrollTop=area.scrollHeight;const p=state.interests.matches.find(x=>x.id===state.selectedChat);if(p&&$("#chat-head"))$("#chat-head").textContent=`Chat with ${p.name}`;}catch(e){if(!silent)toast(e.message)}}

function openMatchModal(){const pieces=Array.from({length:20},(_,i)=>`<i style="left:${4+(i*37)%92}%;animation-delay:${(i%6)*.12}s">${i%2?"♥":"✦"}</i>`).join("");showModal(`<div class="modal match-modal"><button class="close" id="modal-close">${icon("x",17)}</button><div class="confetti">${pieces}</div><div class="match-faces"><span>🧑🏻</span><span class="match-heart">${icon("heart",35)}</span><span>👩🏻</span></div><div class="eyebrow centered">✦ mutual connection</div><h2>It's a Match! ❤️</h2><p>You both said yes. This is where the conversation starts.</p><div class="match-actions"><button class="btn btn-primary" id="match-chat">${icon("message",17)} Send a Message</button><button class="btn btn-outline" id="match-browse">Keep Browsing</button></div></div>`);$("#modal-close").onclick=closeModal;$("#match-browse").onclick=closeModal;$("#match-chat").onclick=()=>{closeModal();scrollToId("messages");showSticker("It's a match! 💘","Go say hello — your chat is ready.","match");}}

function showModal(html){let r=$("#modal-root");if(!r){r=document.createElement("div");r.id="modal-root";document.body.appendChild(r)}r.innerHTML=`<div class="modal-backdrop">${html}</div>`;r.querySelector(".modal-backdrop").onclick=e=>{if(e.target.classList.contains("modal-backdrop"))closeModal();}}
function closeModal(){ $("#modal-root")?.remove(); }

async function logout(){try{await api("/api/auth/logout",{method:"POST"});clearInterval(state.chatPolling);state.me=null;state.profile=null;renderHome();showSticker("See you soon! 👋","Come back anytime for more matches.","message");}catch(e){toast(e.message)}}

async function renderAdmin(){try{const d=await api("/api/admin/overview");$("#app").innerHTML=`<div class="shell"><header class="topbar"><a class="brand" href="#"><span class="brand-badge">${icon("heart",17)}</span>SoulMate Admin</a><div class="nav-actions"><button id="theme-btn" class="icon-btn"></button><button id="logout" class="btn btn-outline">Logout</button></div></header><main><section><div class="container"><div class="section-title"><div><div class="eyebrow">◎ Administrator</div><h2>Moderation Dashboard</h2><p>Approve profiles, manage users, and review reports.</p></div></div><div class="dashboard">${[["Total users",d.stats.totalUsers],["Pending profiles",d.stats.pendingProfiles],["Active users",d.stats.activeUsers],["Open reports",d.stats.reports]].map(x=>`<div class="dash-card"><b>${x[1]}</b><span>${x[0]}</span></div>`).join("")}</div></div></section><section><div class="container"><div class="card"><div class="admin-tabs"><button class="admin-tab active" data-admin-tab="users">Users</button><button class="admin-tab" data-admin-tab="profiles">Profiles</button><button class="admin-tab" data-admin-tab="reports">Reports</button></div><div id="admin-users" class="admin-panel active"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Profile</th><th>Action</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${escapeHTML(u.name)}</td><td>${escapeHTML(u.email)}</td><td>${u.status}</td><td>${u.profileApproved?"Approved":"Pending"}</td><td>${u.profileApproved?"<span class=\"state-pill success\">Approved</span>":`<button class="btn btn-success admin-action" data-id="${u.id}" data-action="approve">Approve</button>`} ${u.status==="blocked"?`<button class="btn btn-outline admin-action" data-id="${u.id}" data-action="unblock">Unblock</button>`:`<button class="btn btn-danger admin-action" data-id="${u.id}" data-action="block">Block</button>`}</td></tr>`).join("")}</tbody></table></div><div id="admin-profiles" class="admin-panel"><div class="admin-profile-grid">${d.profiles.map(p=>`<div class="admin-profile-card"><img src="${escapeAttr(p.photo||fallbackPhoto(p.gender))}" alt="${escapeAttr(p.name)}"><div><b>${escapeHTML(p.name)}, ${p.age}</b><small>${escapeHTML(p.city||"")} · ${p.approved?"Approved":"Pending"}</small></div><button class="btn ${p.approved?"btn-outline":"btn-success"} admin-action" data-id="${p.id}" data-action="${p.approved?"block":"approve"}">${p.approved?"Block user":"Approve profile"}</button></div>`).join("")||'<div class="empty">No profiles to review.</div>'}</div></div><div id="admin-reports" class="admin-panel"><table class="admin-table"><thead><tr><th>Reporter</th><th>Target</th><th>Reason</th><th>Status</th></tr></thead><tbody>${d.reports.length?d.reports.map(r=>`<tr><td>${escapeHTML(r.reporter)}</td><td>${escapeHTML(r.target)}</td><td>${escapeHTML(r.reason)}</td><td>${escapeHTML(r.status)}</td></tr>`).join(""):`<tr><td colspan="4">No reports.</td></tr>`}</tbody></table></div></div></div></section></main></div>`;setTheme();$("#theme-btn").onclick=toggleTheme;$("#logout").onclick=logout;bindAdmin();}catch(e){toast(e.message);}
}
function bindAdmin(){$$(".admin-tab").forEach(b=>b.onclick=()=>{$$(".admin-tab").forEach(x=>x.classList.remove("active"));$$(".admin-panel").forEach(x=>x.classList.remove("active"));b.classList.add("active");$("#admin-"+b.dataset.adminTab).classList.add("active")});$$('.admin-action').forEach(b=>b.onclick=async()=>{try{await api(`/api/admin/users/${b.dataset.id}/${b.dataset.action}`,{method:"POST"});toast("Admin action completed.");renderAdmin();}catch(e){toast(e.message)}})}

async function loadMe(){try{const data=await api("/api/me");state.me=data.user;state.profile=data.profile;if(state.me.role==="admin")await renderAdmin();else renderDashboard();}catch{renderHome();}}
loadMe();
